<?php
defined('BASEPATH') OR exit('No direct script access allowed');

class Spmi_audits_model extends CI_Model
{
    public function cycles() { return $this->db->select("c.*, ou.code AS organization_unit_code, ou.name AS organization_unit_name, ou.type AS organization_unit_type, COUNT(DISTINCT CASE WHEN s.id IS NULL OR s.status IN ('draft', 'returned_for_revision') THEN a.id END) AS pending_auditee_count, COUNT(DISTINCT CASE WHEN s.status IN ('submitted', 'resubmitted') AND (aa.id IS NULL OR aa.status != 'finalized') THEN a.id END) AS pending_auditor_count", FALSE)->from('spmi_audit_cycles c')->join('organization_units ou', 'ou.id = c.organization_unit_id', 'left')->join('spmi_audit_assignments a', 'a.cycle_id = c.id', 'left')->join('spmi_auditee_submissions s', 's.assignment_id = a.id', 'left')->join('spmi_auditor_assessments aa', 'aa.assignment_id = a.id AND aa.source_submission_version = s.version', 'left')->group_by('c.id')->order_by('c.start_date', 'DESC')->order_by('c.id', 'DESC')->get()->result(); }
    public function cycle($id, $for_update = FALSE) { $select = 'SELECT c.*, ou.code AS organization_unit_code, ou.name AS organization_unit_name, ou.type AS organization_unit_type FROM spmi_audit_cycles c LEFT JOIN organization_units ou ON ou.id = c.organization_unit_id WHERE c.id = ' . (int) $id; return $for_update ? $this->db->query($select . ' FOR UPDATE')->row() : $this->db->query($select)->row(); }
    public function cycle_by_code($code, $exclude = 0) { $this->db->where('cycle_code', $code); if ($exclude) $this->db->where('id !=', (int) $exclude); return $this->db->get('spmi_audit_cycles')->row(); }
    public function insert_cycle($data) { return $this->db->insert('spmi_audit_cycles', $data) ? $this->db->insert_id() : 0; }
    public function update_cycle($id, $data) { return $this->db->where('id', (int) $id)->update('spmi_audit_cycles', $data); }
    public function assignments($cycle_id) { return $this->db->select('a.*, s.status AS submission_status, aa.status AS assessment_status')->from('spmi_audit_assignments a')->join('spmi_auditee_submissions s', 's.assignment_id = a.id', 'left')->join('spmi_auditor_assessments aa', 'aa.assignment_id = a.id AND aa.source_submission_version = s.version', 'left')->where('a.cycle_id', (int) $cycle_id)->order_by('a.id', 'ASC')->get()->result(); }
    public function assignment($id) { return $this->db->where('id', (int) $id)->get('spmi_audit_assignments')->row(); }
    public function assignment_by_standard_auditee($cycle_id, $standard_id, $auditee_id) { return $this->db->where(['cycle_id' => (int) $cycle_id, 'source_standard_id' => (int) $standard_id, 'auditee_id' => (int) $auditee_id])->get('spmi_audit_assignments')->row(); }
    public function insert_assignment($data) { return $this->db->insert('spmi_audit_assignments', $data) ? $this->db->insert_id() : 0; }
    public function insert_item($data) { return $this->db->insert('spmi_audit_assignment_items', $data) ? $this->db->insert_id() : 0; }
    public function insert_rubric($data) { return $this->db->insert('spmi_audit_assignment_item_rubrics', $data); }
    public function items($assignment_id) { return $this->db->where('assignment_id', (int) $assignment_id)->order_by('display_order', 'ASC')->get('spmi_audit_assignment_items')->result(); }
    public function rubrics($item_id) { return $this->db->where('assignment_item_id', (int) $item_id)->order_by('score', 'ASC')->get('spmi_audit_assignment_item_rubrics')->result(); }
    public function assignment_workspace_descendant_exists($assignment_id) { foreach (['spmi_auditee_submissions', 'spmi_auditor_assessments', 'spmi_auditee_submission_revision_events'] as $table) { if ($this->db->select('1', FALSE)->where('assignment_id', (int) $assignment_id)->limit(1)->get($table)->num_rows() > 0) return TRUE; } return FALSE; }
    public function delete_assignment_children($id) { $items = $this->items($id); foreach ($items as $item) { if (!$this->db->where('assignment_item_id', (int) $item->id)->delete('spmi_audit_assignment_item_rubrics')) return FALSE; } return $this->db->where('assignment_id', (int) $id)->delete('spmi_audit_assignment_items'); }
    public function delete_assignment($id) { return $this->db->where('id', (int) $id)->delete('spmi_audit_assignments'); }
    public function versions() { return $this->db->select('v.*')->from('spmi_versions v')->join('spmi_standards s', 's.version_id = v.id')->where_in('v.status', ['draft', 'review'])->group_by('v.id')->order_by('v.id', 'DESC')->get()->result(); }
    public function standards_by_version() { return $this->db->select('s.id, s.version_id, s.standard_code, s.title, s.display_order')->from('spmi_standards s')->join('spmi_versions v', 'v.id = s.version_id')->where_in('v.status', ['draft', 'review'])->order_by('v.id', 'DESC')->order_by('s.display_order', 'ASC')->get()->result(); }
    public function standards_for_version_for_update($version_id, $standard_ids = []) { $sql = 'SELECT s.* FROM spmi_standards s WHERE s.version_id = ' . (int) $version_id; if ($standard_ids) $sql .= ' AND s.id IN (' . implode(',', array_map('intval', $standard_ids)) . ')'; return $this->db->query($sql . ' ORDER BY s.display_order ASC FOR UPDATE')->result(); }
    public function version_for_update($id) { return $this->db->query('SELECT * FROM spmi_versions WHERE id = ' . (int) $id . ' FOR UPDATE')->row(); }
    public function standard_indicators($standard_id) { return $this->db->where('standard_id', (int) $standard_id)->order_by('indicator_code', 'ASC')->get('spmi_indicators')->result(); }
    public function users_by_role($role) { return $this->db->where('role', $role)->order_by('nama', 'ASC')->get('users')->result(); }
    public function user($id) { return $this->db->where('id', (int) $id)->get('users')->row(); }
    public function cycle_has_assignments($cycle_id) { return $this->db->select('1', FALSE)->where('cycle_id', (int) $cycle_id)->limit(1)->get('spmi_audit_assignments')->num_rows() > 0; }
    public function active_supported_units() { return $this->db->where('is_active', 1)->where_in('type', ['study_program', 'faculty', 'bureau', 'unit', 'institute'])->order_by('type', 'ASC')->order_by('code', 'ASC')->get('organization_units')->result(); }
    public function active_supported_unit($id, $for_update = FALSE) { $sql = "SELECT * FROM organization_units WHERE id = " . (int) $id . " AND is_active = 1 AND type IN ('study_program', 'faculty', 'bureau', 'unit', 'institute')"; return $for_update ? $this->db->query($sql . ' FOR UPDATE')->row() : $this->db->query($sql)->row(); }
    public function unit_users_by_role($unit, $role) { if ($unit->type === 'study_program') return $this->db->distinct()->select('u.*')->from('staf_prodi sp')->join('profil_prodi pp', 'pp.id = sp.id_prodi')->join('users u', 'u.id = sp.id_akun')->where('pp.organization_unit_id', (int) $unit->id)->where('sp.status', 'active')->where('u.role', $role)->order_by('u.nama', 'ASC')->order_by('u.email', 'ASC')->get()->result(); return $this->db->distinct()->select('u.*')->from('user_unit_assignments uua')->join('users u', 'u.id = uua.user_id')->where('uua.organization_unit_id', (int) $unit->id)->where('uua.valid_from <= CURDATE()', NULL, FALSE)->group_start()->where('uua.valid_until IS NULL', NULL, FALSE)->or_where('uua.valid_until > CURDATE()', NULL, FALSE)->group_end()->where('u.role', $role)->order_by('u.nama', 'ASC')->order_by('u.email', 'ASC')->get()->result(); }
    public function unit_user_by_role($unit, $user_id, $role) { if ($unit->type === 'study_program') return $this->db->select('u.id')->from('staf_prodi sp')->join('profil_prodi pp', 'pp.id = sp.id_prodi')->join('users u', 'u.id = sp.id_akun')->where('pp.organization_unit_id', (int) $unit->id)->where('sp.status', 'active')->where(['u.id' => (int) $user_id, 'u.role' => $role])->get()->row(); return $this->db->select('u.id')->from('user_unit_assignments uua')->join('users u', 'u.id = uua.user_id')->where('uua.organization_unit_id', (int) $unit->id)->where('uua.valid_from <= CURDATE()', NULL, FALSE)->group_start()->where('uua.valid_until IS NULL', NULL, FALSE)->or_where('uua.valid_until > CURDATE()', NULL, FALSE)->group_end()->where(['u.id' => (int) $user_id, 'u.role' => $role])->get()->row(); }
    public function locked_unit_user_by_role($unit, $user_id, $role) { if ($unit->type === 'study_program') return $this->db->query("SELECT u.id FROM staf_prodi sp JOIN profil_prodi pp ON pp.id = sp.id_prodi JOIN users u ON u.id = sp.id_akun WHERE pp.organization_unit_id = " . (int) $unit->id . " AND sp.status = 'active' AND u.id = " . (int) $user_id . " AND u.role = " . $this->db->escape($role) . ' FOR UPDATE')->row(); return $this->db->query("SELECT u.id FROM user_unit_assignments uua JOIN users u ON u.id = uua.user_id WHERE uua.organization_unit_id = " . (int) $unit->id . " AND uua.valid_from <= CURDATE() AND (uua.valid_until IS NULL OR uua.valid_until > CURDATE()) AND u.id = " . (int) $user_id . " AND u.role = " . $this->db->escape($role) . ' FOR UPDATE')->row(); }
}
